    ) VALUES (
        @ScenarioVersionId_BEG_WMS_01_V1, N'Lê Thu Trang', N'QA Assistant', N'Đảm bảo chất lượng', N'Đối chiếu nhiệt độ với biên bản QA, yêu cầu giữ hàng khi nghi ngờ lệch nhiệt, tổng hợp sự cố tuần cho khách 3PL.',
        N'Muốn mỗi sự cố nhiệt độ có mã, thời điểm, mức, hành động và chữ ký ca — đủ để trả lời audit nhẹ.', N'Phải lục chat Zalo để ghép lại timeline; thiếu trường “nhiệt độ cao nhất ghi nhận”.', N'Báo cáo QA thiếu chứng cứ khi khách hỏi; sợ form quá ngắn bị audit nội bộ từ chối.', N'Cẩn thận, thích bảng trường dữ liệu, nói chậm. Sẵn sàng chia sẻ mẫu biên bản nếu được hỏi.', N'Kỷ luật, hợp tác, đôi khi bảo thủ với thay đổi làm mất dấu vết QA.', 2, 1
    );
END;
