DECLARE @ScenarioVersionId_BEG_PROMO_01_V1 int;
SELECT @ScenarioVersionId_BEG_PROMO_01_V1 = [Id] FROM [scenario].[ScenarioVersions] WHERE [ScenarioId] = @ScenarioId_BEG_PROMO_01_V1 AND [VersionNo] = 1;
IF @ScenarioVersionId_BEG_PROMO_01_V1 IS NULL
BEGIN
    INSERT INTO [scenario].[ScenarioVersions] (
        [ScenarioId], [VersionNo], [Summary], [BusinessContext], [BusinessProblem], [BusinessObjectives],
        [BARole], [Assignment], [InScope], [OutOfScope], [KnownConstraints], [Difficulty], [IsFreeAccess],
        [Status], [IsPublished], [PublishedAt], [CreatedAt]
    ) VALUES (
        @ScenarioId_BEG_PROMO_01_V1, 1, N'Làm rõ điều kiện voucher GIẢM50K giữa banner Marketing, app và POS để giảm khiếu nại mã không dùng được.', N'MegaFashion Starter là chuỗi thời trang casual với app bán hàng và 6 cửa hàng. Tuần này chạy chiến dịch voucher **GIẢM50K**: giảm 50.000đ cho đơn từ 499.000đ. Banner quảng cáo ghi “mọi sản phẩm”, trong khi Promotion Engine chỉ áp dụng danh mục **Áo**. POS cửa hàng đôi khi báo lỗi khác app. CX Specialist nhận khoảng 40–60 inbox/ngày liên quan mã trong ngày flash nhẹ.', N'1) Điều kiện trên banner khác cấu hình hệ thống (danh mục Áo, không cộng dồn FREESHIP). 2) Marketing Ops, POS Supervisor và CX hiểu rule khác nhau. 3) Chưa có bảng rule đơn giản + AC để BA trainee luyện đặc tả voucher.', N'1) Liệt kê điều kiện voucher as-is (min order, danh mục, stacking, giới hạn dùng). 2) Chỉ ra chỗ lệch banner vs hệ thống vs POS. 3) Viết 3 acceptance criteria / user stories cho voucher mẫu GIẢM50K. 4) Hoàn thành deliverable Beginner (không thiết kế engine điểm thưởng phức tạp).',
        N'Bạn là Junior BA hỗ trợ Marketing Ops của MegaFashion Starter, làm rõ điều kiện voucher và đồng bộ wording giữa banner, app và POS.', N'Sprint 1: BAP ngắn + stakeholder map (Marketing Ops, POS Supervisor, CX Specialist). Sprint 2: Phỏng vấn 3 bên; ghi notes về lệch banner/POS. Sprint 3: Bảng điều kiện voucher as-is / to-be và danh sách chỗ lệch. Sprint 4: 3 user stories + AC cho GIẢM50K; phản ánh nhẹ sự kiện E1 nếu có.', N'- Một voucher tiền mặt cố định GIẢM50K: min order, danh mục, không cộng dồn, giới hạn 1 mã/tài khoản/ngày. - Đồng bộ mô tả điều kiện trên banner/app/POS. - Deliverable Beginner: BAP ngắn, stakeholder map, interview notes, as-is/to-be, 3 user stories + AC.', N'- Engine điểm thưởng phức tạp, cá nhân hóa AI, đa voucher stacking nâng cao. - Đổi chính sách giá gốc SKU toàn chuỗi.', N'- Không đổi chính sách giá gốc sản phẩm trong bài tập. - Giữ mã FREESHIP hoạt động song song nhưng không cộng dồn với GIẢM50K. - Số liệu khiếu nại là giả lập đào tạo.', N'Beginner', 0,
        N'Published', 1, SYSDATETIMEOFFSET(), SYSDATETIMEOFFSET()
    );
    SET @ScenarioVersionId_BEG_PROMO_01_V1 = SCOPE_IDENTITY();
END;
